const t   = $('Loop Over Items').first().json;
const row = $input.first().json || {};
const e   = t.expect;
const problems = [];

if (e) {
  const has = (a, b) => String(a || '').toLowerCase().includes(String(b).toLowerCase());
  if (e.reply_contains !== undefined && !has(row.reply, e.reply_contains))
    problems.push('reply should mention "' + e.reply_contains + '"');
  if (e.state !== undefined && row.state !== e.state)
    problems.push('conversation state should be ' + e.state);
  if (e.escalation !== undefined && row.escalation !== e.escalation)
    problems.push('newest escalation should be ' + e.escalation);
  if (e.audit_event && Number(row.audit_count) < 1)
    problems.push('audit log should contain ' + e.audit_event);
  if (e.message_rows !== undefined && Number(row.message_rows) !== e.message_rows)
    problems.push('message should be stored ' + e.message_rows + ' time(s)');
  if (e.reply_rows !== undefined && Number(row.reply_rows) !== e.reply_rows)
    problems.push('message should be answered ' + e.reply_rows + ' time(s)');
  if (e.new_order_total !== undefined && row.new_order_total !== e.new_order_total)
    problems.push('new order total should be ' + e.new_order_total);
}

const short = s => String(s || '').replace(/\s+/g, ' ').slice(0, 90);
return [{ json: {
  test: t.id, name: t.name,
  result: !e ? 'step' : (problems.length ? 'FAIL' : 'PASS'),
  sent: t.text, expected: t.expected_text,
  actual: `reply: "${short(row.reply)}" | state: ${row.state} | escalation: ${row.escalation}`,
  problems: problems.join('; ')
} }];

const rows = $input.all().map(i => i.json);
const checked = rows.filter(r => r.result !== 'step');
const passed  = checked.filter(r => r.result === 'PASS').length;
const failed  = checked.filter(r => r.result === 'FAIL').map(r => r.test);

const summary = { test: 'SUMMARY', name: passed + ' of ' + checked.length + ' checks passed',
  result: failed.length ? 'FAILURES' : 'ALL PASS', sent: '', expected: '', actual: '',
  problems: failed.join(', ') };

return [summary, ...rows].map(r => ({ json: r }));
